import { ethers } from "ethers";
import { Network, getBridgeConfig } from "../consts/bridgeRoutes";
import { EnvValidationError } from "./errors";
import { FallbackRpcProvider } from "./fallbackProvider";
import { defaultEmitter } from "./emitter";

/**
 * The slice of a provider the preflight needs. Kept minimal so the checks can be
 * exercised without a chain.
 */
export interface PreflightProvider {
  getNetwork(): Promise<{ chainId: number | bigint }>;
  getCode(address: string): Promise<string>;
  getBalance(address: string): Promise<bigint>;
}

export interface ValidatedEnvironment {
  signerAddress: string;
  chainIds: number[];
  networks: Network[];
  envioUrl: string;
  warnings: string[];
}

export interface ValidateEnvironmentParams {
  env?: Record<string, string | undefined>;
  fetchBridgeConfig?: typeof getBridgeConfig;
  createProvider?: (urls: string[], expectedChainId: number) => PreflightProvider;
  readDepositTokenBalance?: (
    token: string,
    owner: string,
    spender: string,
    provider: PreflightProvider
  ) => Promise<{ balance: bigint; allowance: bigint }>;
}

const splitList = (value: string | undefined): string[] =>
  (value ?? "")
    .split(",")
    .map((entry) => entry.trim())
    .filter((entry) => entry.length > 0);

const isHttpUrl = (value: string): boolean => {
  try {
    const url = new URL(value);
    return url.protocol === "http:" || url.protocol === "https:";
  } catch {
    return false;
  }
};

const ERC20_ABI = [
  "function balanceOf(address) view returns (uint256)",
  "function allowance(address,address) view returns (uint256)",
];

/**
 * Build a provider for the preflight to probe with.
 *
 * Deliberately constructed *without* the expected chain id. FallbackRpcProvider
 * short-circuits `_detectNetwork` to the configured value when it is given one,
 * which would make the chain-id check compare the expectation against itself and
 * silently pass an endpoint pointed at the wrong network.
 */
export const defaultCreateProvider = (urls: string[], _expectedChainId: number): PreflightProvider =>
  new FallbackRpcProvider(urls, defaultEmitter) as unknown as PreflightProvider;

const defaultReadDepositTokenBalance = async (
  token: string,
  owner: string,
  spender: string,
  provider: PreflightProvider
): Promise<{ balance: bigint; allowance: bigint }> => {
  const erc20 = new ethers.Contract(token, ERC20_ABI, provider as any);
  const [balance, allowance] = await Promise.all([
    erc20.balanceOf(owner),
    spender ? erc20.allowance(owner, spender) : Promise.resolve(0n),
  ]);
  return { balance: BigInt(balance), allowance: BigInt(allowance) };
};

/**
 * Validate the whole environment before the bot does anything else.
 *
 * Every problem is collected and reported together: fixing one variable,
 * restarting, and discovering the next one is a slow way to configure a
 * validator. Static checks run first and abort before any network call, so a
 * typo never costs an RPC round trip.
 *
 * @returns The validated configuration, with any non-fatal warnings
 * @throws EnvValidationError listing every problem found
 */
export const validateEnvironment = async ({
  env = process.env,
  fetchBridgeConfig = getBridgeConfig,
  createProvider = defaultCreateProvider,
  readDepositTokenBalance = defaultReadDepositTokenBalance,
}: ValidateEnvironmentParams = {}): Promise<ValidatedEnvironment> => {
  const problems: string[] = [];
  const warnings: string[] = [];

  const signerAddress = validatePrivateKey(env, problems);
  const chainIds = validateChainIds(env, problems, fetchBridgeConfig);
  const networks = validateNetworks(env, problems);
  const envioUrl = validateEnvioUrl(env, problems);
  validateRoutes(chainIds, problems, fetchBridgeConfig);

  if (problems.length > 0) throw new EnvValidationError(problems);

  await runPreflight({
    chainIds,
    networks,
    signerAddress,
    problems,
    warnings,
    fetchBridgeConfig,
    createProvider,
    readDepositTokenBalance,
  });

  if (problems.length > 0) throw new EnvValidationError(problems);

  return { signerAddress, chainIds, networks, envioUrl, warnings };
};

interface PreflightParams {
  chainIds: number[];
  networks: Network[];
  signerAddress: string;
  problems: string[];
  warnings: string[];
  fetchBridgeConfig: typeof getBridgeConfig;
  createProvider: (urls: string[], expectedChainId: number) => PreflightProvider;
  readDepositTokenBalance: (
    token: string,
    owner: string,
    spender: string,
    provider: PreflightProvider
  ) => Promise<{ balance: bigint; allowance: bigint }>;
}

/** One endpoint the bot will actually talk to, and what it is expected to be. */
interface Endpoint {
  role: "inbox" | "outbox" | "router";
  envVar: string;
  urls: string[];
  expectedChainId: number;
  provider: PreflightProvider;
}

/**
 * Confirm the configured environment describes a chain the bot can actually work
 * on: every endpoint answers as the chain we think it is, the contracts we are
 * about to call exist, and the signer can pay for gas.
 *
 * Funding is reported rather than enforced, with one exception: a signer with
 * zero native balance cannot send any transaction at all, so that is fatal. A
 * balance merely below the deposit is runtime state, not misconfiguration, and
 * refusing to start on it would turn a transient funding gap into a dead bot.
 */
const runPreflight = async ({
  chainIds,
  networks,
  signerAddress,
  problems,
  warnings,
  fetchBridgeConfig,
  createProvider,
  readDepositTokenBalance,
}: PreflightParams): Promise<void> => {
  for (const chainId of chainIds) {
    const bridge = fetchBridgeConfig(chainId) as any;
    const { rpcEnvVars } = bridge;

    const endpoints: Endpoint[] = [
      {
        role: "outbox",
        envVar: rpcEnvVars.outbox,
        urls: bridge.outboxRPC,
        expectedChainId: chainId,
        provider: createProvider(bridge.outboxRPC, chainId),
      },
      {
        role: "inbox",
        envVar: rpcEnvVars.inbox,
        urls: bridge.inboxRPC,
        expectedChainId: bridge.inboxChainId,
        provider: createProvider(bridge.inboxRPC, bridge.inboxChainId),
      },
    ];
    if (rpcEnvVars.router && bridge.routerRPC) {
      endpoints.push({
        role: "router",
        envVar: rpcEnvVars.router,
        urls: bridge.routerRPC,
        expectedChainId: bridge.routerChainId,
        provider: createProvider(bridge.routerRPC, bridge.routerChainId),
      });
    }

    const reachable = await checkEndpointChains(endpoints, chainId, problems);
    await checkDeployments(reachable, bridge, networks, chainId, problems);
    await checkFunding(
      reachable,
      bridge,
      networks,
      chainId,
      signerAddress,
      problems,
      warnings,
      readDepositTokenBalance
    );
  }
};

/** Confirm each endpoint answers as the chain it is configured to be. */
const checkEndpointChains = async (endpoints: Endpoint[], chainId: number, problems: string[]): Promise<Endpoint[]> => {
  const reachable: Endpoint[] = [];
  for (const endpoint of endpoints) {
    try {
      const network = await endpoint.provider.getNetwork();
      const reported = Number(network.chainId);
      if (reported !== endpoint.expectedChainId) {
        problems.push(
          `${endpoint.envVar} (chain ${chainId} ${endpoint.role}) answers as chain ${reported}, expected ${endpoint.expectedChainId}.`
        );
        continue;
      }
      reachable.push(endpoint);
    } catch (error) {
      problems.push(
        `${endpoint.envVar} (chain ${chainId} ${endpoint.role}) is unreachable: ${(error as Error)?.message}`
      );
    }
  }
  return reachable;
};

/** Confirm the contracts we are about to call are deployed where we think. */
const checkDeployments = async (
  endpoints: Endpoint[],
  bridge: any,
  networks: Network[],
  chainId: number,
  problems: string[]
): Promise<void> => {
  const roleToContract: Record<string, string> = { inbox: "veaInbox", outbox: "veaOutbox", router: "veaRouter" };
  for (const network of networks) {
    const route = bridge.routeConfig[network];
    if (!route) {
      problems.push(`Chain ${chainId} has no ${network} deployment, but NETWORKS asks for it.`);
      continue;
    }
    for (const endpoint of endpoints) {
      const contract = route[roleToContract[endpoint.role]];
      if (!contract?.address) continue;
      try {
        const code = await endpoint.provider.getCode(contract.address);
        if (!code || code === "0x") {
          problems.push(`Chain ${chainId} ${network} ${endpoint.role} has no contract code at ${contract.address}.`);
        }
      } catch (error) {
        problems.push(
          `Chain ${chainId} ${network} ${endpoint.role} code check at ${contract.address} failed: ${
            (error as Error)?.message
          }`
        );
      }
    }
  }
};

/** Report what the signer can pay with; fail only when it can pay nothing. */
const checkFunding = async (
  endpoints: Endpoint[],
  bridge: any,
  networks: Network[],
  chainId: number,
  signerAddress: string,
  problems: string[],
  warnings: string[],
  readDepositTokenBalance: PreflightParams["readDepositTokenBalance"]
): Promise<void> => {
  const deposits = networks.map((network) => bridge.routeConfig[network]?.deposit).filter(Boolean) as bigint[];
  const largestDeposit = deposits.length > 0 ? deposits.reduce((a, b) => (a > b ? a : b)) : 0n;

  for (const endpoint of endpoints) {
    if (endpoint.role === "router") continue; // nothing is ever sent to the router chain
    let balance: bigint;
    try {
      balance = await endpoint.provider.getBalance(signerAddress);
    } catch (error) {
      problems.push(`Chain ${chainId} ${endpoint.role} balance check failed: ${(error as Error)?.message}`);
      continue;
    }
    if (balance === 0n) {
      problems.push(
        `Signer ${signerAddress} has no native balance on chain ${chainId} ${endpoint.role}; it cannot pay for gas.`
      );
      continue;
    }
    // Only a native-deposit route needs its balance to cover the deposit too.
    if (!bridge.depositToken && endpoint.role === "outbox" && balance < largestDeposit) {
      warnings.push(
        `Signer native balance on chain ${chainId} (${balance}) is below the deposit (${largestDeposit}); claims and challenges will revert until it is topped up.`
      );
    }
  }

  if (!bridge.depositToken) return;
  const outbox = endpoints.find((endpoint) => endpoint.role === "outbox");
  if (!outbox) return;
  const spender = networks.map((network) => bridge.routeConfig[network]?.veaOutbox?.address).find(Boolean) ?? "";
  try {
    const { balance, allowance } = await readDepositTokenBalance(
      bridge.depositToken,
      signerAddress,
      spender,
      outbox.provider
    );
    if (balance < largestDeposit) {
      warnings.push(`Deposit token balance on chain ${chainId} (${balance}) is below the deposit (${largestDeposit}).`);
    }
    if (allowance < largestDeposit) {
      warnings.push(
        `Deposit token allowance on chain ${chainId} (${allowance}) is below the deposit (${largestDeposit}); it is topped up lazily on first use.`
      );
    }
  } catch (error) {
    problems.push(`Chain ${chainId} deposit token check failed: ${(error as Error)?.message}`);
  }
};

const validatePrivateKey = (env: Record<string, string | undefined>, problems: string[]): string => {
  const privateKey = env.PRIVATE_KEY;
  if (!privateKey) {
    problems.push("PRIVATE_KEY is not set.");
    return "";
  }
  try {
    return new ethers.Wallet(privateKey).address;
  } catch {
    problems.push("PRIVATE_KEY is not a valid private key (expected a 32-byte hex string).");
    return "";
  }
};

const validateChainIds = (
  env: Record<string, string | undefined>,
  problems: string[],
  fetchBridgeConfig: typeof getBridgeConfig
): number[] => {
  const raw = splitList(env.VEAOUTBOX_CHAINS);
  if (raw.length === 0) {
    problems.push("VEAOUTBOX_CHAINS is empty; the validator would have no outbox to watch.");
    return [];
  }
  const chainIds: number[] = [];
  for (const entry of raw) {
    const chainId = Number(entry);
    if (!Number.isInteger(chainId)) {
      problems.push(`VEAOUTBOX_CHAINS contains "${entry}", which is not a chain id.`);
      continue;
    }
    try {
      fetchBridgeConfig(chainId);
    } catch {
      problems.push(`VEAOUTBOX_CHAINS contains ${chainId}, which has no configured bridge.`);
      continue;
    }
    chainIds.push(chainId);
  }
  return chainIds;
};

const validateNetworks = (env: Record<string, string | undefined>, problems: string[]): Network[] => {
  const raw = splitList(env.NETWORKS);
  if (raw.length === 0) {
    problems.push("NETWORKS is empty; the validator would start up and watch nothing.");
    return [];
  }
  const valid = Object.values(Network) as string[];
  const networks: Network[] = [];
  for (const entry of raw) {
    if (!valid.includes(entry)) {
      problems.push(`NETWORKS contains "${entry}"; expected one of: ${valid.join(", ")}.`);
      continue;
    }
    networks.push(entry as Network);
  }
  return networks;
};

const validateEnvioUrl = (env: Record<string, string | undefined>, problems: string[]): string => {
  const envioUrl = env.ENVIO_URL;
  if (!envioUrl) {
    problems.push("ENVIO_URL is not set; the subgraph fallback would fail exactly when it is needed.");
    return "";
  }
  if (!isHttpUrl(envioUrl)) {
    problems.push("ENVIO_URL is not a valid http(s) URL.");
    return "";
  }
  return envioUrl;
};

const validateRoutes = (chainIds: number[], problems: string[], fetchBridgeConfig: typeof getBridgeConfig): void => {
  for (const chainId of chainIds) {
    const bridge = fetchBridgeConfig(chainId) as any;
    const { rpcEnvVars } = bridge;

    const endpoints: Array<[string, string[] | undefined]> = [
      [rpcEnvVars.inbox, bridge.inboxRPC],
      [rpcEnvVars.outbox, bridge.outboxRPC],
    ];
    if (rpcEnvVars.router) endpoints.push([rpcEnvVars.router, bridge.routerRPC]);

    for (const [envVar, urls] of endpoints) {
      if (!urls || urls.length === 0) {
        problems.push(`${envVar} is empty but chain ${chainId} needs it.`);
        continue;
      }
      for (const url of urls) {
        if (!isHttpUrl(url)) problems.push(`${envVar} contains "${url}", which is not an http(s) URL.`);
      }
    }

    if (bridge.depositTokenEnvVar && !bridge.depositToken) {
      problems.push(`${bridge.depositTokenEnvVar} is not set but chain ${chainId} takes its deposit in that token.`);
    }
  }
};

import { EventEmitter } from "node:events";
import { JsonRpcPayload, JsonRpcResult, JsonRpcProvider, Network } from "ethers";
import { BotEvents } from "./botEvents";

type RPCEndpoint = { url: string; label?: string };

/**
 * ethers v6 JSON-RPC provider that transparently fails over to the next endpoint when a request fails.
 */
export class FallbackRpcProvider extends JsonRpcProvider {
  private endpoints: RPCEndpoint[];
  private activeIndex = 0;
  private emitter: EventEmitter;
  private staticChainId?: number;
  private inner: JsonRpcProvider[] = [];

  constructor(endpoints: string | (string | RPCEndpoint)[], emitter: EventEmitter, chainId?: number) {
    const list = Array.isArray(endpoints) ? endpoints : [endpoints];
    const normalized = list.map((e) => (typeof e === "string" ? { url: e } : e));
    if (normalized.length === 0) throw new Error("FallbackRpcProvider requires at least one RPC endpoint");
    super(normalized[0].url, chainId !== undefined ? Network.from(chainId) : undefined);
    this.endpoints = normalized;
    this.emitter = emitter;
    this.staticChainId = chainId;
  }

  async _detectNetwork(): Promise<Network> {
    if (this.staticChainId !== undefined) return Network.from(this.staticChainId);
    return super._detectNetwork();
  }

  private label(i: number) {
    return this.endpoints[i].label ?? this.endpoints[i].url;
  }

  // Overrides the low-level transport so ALL RPC calls (including internal ones like eth_chainId) go through fallback logic.
  async _send(payload: JsonRpcPayload | Array<JsonRpcPayload>): Promise<Array<JsonRpcResult>> {
    const method = Array.isArray(payload) ? "batch" : payload.method;
    let lastErr: any;
    for (let attempt = 0; attempt < this.endpoints.length; attempt++) {
      const i = (this.activeIndex + attempt) % this.endpoints.length;
      try {
        const result = await this.getInner(i)._send(payload);
        if (i !== this.activeIndex) {
          this.emitter.emit(BotEvents.RPC_RECOVERED, { method, from: this.label(this.activeIndex), to: this.label(i) });
          this.activeIndex = i;
        }
        return result;
      } catch (err: any) {
        lastErr = err;
        this.emitter.emit(BotEvents.RPC_FAILURE, {
          method,
          from: this.label(this.activeIndex),
          to: this.label(i),
          err,
        });
      }
    }
    throw lastErr;
  }

  private getInner(i: number) {
    if (!this.inner[i]) {
      this.inner[i] = new JsonRpcProvider(
        this.endpoints[i].url,
        this.staticChainId !== undefined ? Network.from(this.staticChainId) : undefined
      );
    }
    return this.inner[i];
  }
}

import { getBridgeConfig, Network } from "./consts/bridgeRoutes";
import { getVeaInbox, getVeaOutbox } from "./utils/ethers";
import { FallbackRpcProvider } from "./utils/fallbackProvider";
import { FallbackProviderV5 } from "./utils/fallbackProviderV5";
import { setEpochRange } from "./utils/epochHandler";
import { defaultEmitter } from "./utils/emitter";
import { BotEvents } from "./utils/botEvents";
import { initialize as initializeLogger } from "./utils/logger";
import { ShutdownSignal } from "./utils/shutdown";
import { getBotPath, BotPaths, getNetworkConfig, NetworkConfig } from "./utils/botConfig";
import { getClaim } from "./utils/claim";
import { CheckAndClaimParams, checkAndClaim } from "./helpers/claimer";
import { ChallengeAndResolveClaimParams, challengeAndResolveClaim } from "./helpers/validator";
import { saveSnapshot, SaveSnapshotParams } from "./helpers/snapshot";
import { getTransactionHandler } from "./utils/transactionHandlers";
import { validateEnvironment } from "./utils/envValidation";

const CYCLE_DELAY_MS = 2 * 60 * 1000; // 2 minutes

/**
 * @file This file contains the logic for watching bridge and validating/resolving for claims.
 *
 * @param shutDownSignal - The signal to shut down the watcher
 * @param emitter - The emitter to emit events
 *
 */

export const watch = async (
  shutDownSignal: ShutdownSignal = new ShutdownSignal(),
  emitter: typeof defaultEmitter = defaultEmitter
) => {
  initializeLogger(emitter);
  // Validate the whole environment before anything else, including before the
  // first heartbeat: a bot that reports "started" and then dies on a missing
  // variable looks alive to whatever is watching it.
  const validatedEnv = await validateEnvironment();
  emitter.emit(BotEvents.ENV_VALIDATED, validatedEnv.signerAddress, validatedEnv.chainIds, validatedEnv.networks);
  for (const warning of validatedEnv.warnings) emitter.emit(BotEvents.ENV_WARNING, warning);
  const cliCommand = process.argv;
  const { path, toSaveSnapshot } = getBotPath({ cliCommand });
  const networkConfigs = getNetworkConfig();
  emitter.emit(BotEvents.STARTED, path, networkConfigs[0].networks);
  const transactionHandlers: { [key: string]: any } = {};
  const toWatch: { [key: string]: { count: number; epochs: number[] } } = {};
  while (!shutDownSignal.getIsShutdownSignal()) {
    for (const networkConfig of networkConfigs) {
      await processNetwork(path, toSaveSnapshot, networkConfig, transactionHandlers, toWatch, emitter);
    }
    await wait(CYCLE_DELAY_MS);
  }
};

async function processNetwork(
  path: number,
  toSaveSnapshot: boolean,
  networkConfig: NetworkConfig,
  transactionHandlers: { [key: string]: any },
  toWatch: { [key: string]: { count: number; epochs: number[] } },
  emitter: typeof defaultEmitter
): Promise<void> {
  const { chainId, networks } = networkConfig;
  const { routeConfig, inboxRPC, outboxRPC, routerRPC } = getBridgeConfig(chainId);
  for (const network of networks) {
    emitter.emit(BotEvents.WATCHING, chainId, network);
    const networkKey = `${chainId}_${network}`;
    if (!toWatch[networkKey]) {
      toWatch[networkKey] = { count: -1, epochs: [] };
    }
    const veaOutboxProvider = new FallbackProviderV5(outboxRPC, emitter);
    let veaOutboxLatestBlock = await veaOutboxProvider.getBlock("latest");

    // If the watcher has already started, only check the latest epoch
    if (network == Network.DEVNET) {
      toWatch[networkKey].epochs = [Math.floor(veaOutboxLatestBlock.timestamp / routeConfig[network].epochPeriod)];
    } else if (toWatch[networkKey].epochs.length == 0) {
      const epochRange = setEpochRange({
        chainId,
        currentTimestamp: veaOutboxLatestBlock.timestamp,
        epochPeriod: routeConfig[network].epochPeriod,
      });
      toWatch[networkKey].epochs = epochRange;
    }

    await processEpochsForNetwork({
      chainId,
      path,
      toSaveSnapshot,
      networkKey,
      network,
      routeConfig,
      inboxRPC,
      outboxRPC,
      routerRPC,
      toWatch,
      transactionHandlers,
      emitter,
    });
    const currentLatestBlock = await veaOutboxProvider.getBlock("latest");
    const currentClaimableEpoch = Math.floor(currentLatestBlock.timestamp / routeConfig[network].epochPeriod) - 1;

    const toWatchEpochs = toWatch[networkKey];
    const lastEpochInToWatch = toWatchEpochs[toWatchEpochs.epochs.length - 1];
    if (currentClaimableEpoch > lastEpochInToWatch) {
      toWatch[networkKey].epochs.push(currentClaimableEpoch);
    }
  }
}

interface ProcessEpochParams {
  chainId: number;
  path: number;
  toSaveSnapshot: boolean;
  networkKey: string;
  network: Network;
  routeConfig: any;
  inboxRPC: string[];
  outboxRPC: string[];
  routerRPC: string[] | undefined;
  toWatch: { [key: string]: { count: number; epochs: number[] } };
  transactionHandlers: { [key: string]: any };
  emitter: typeof defaultEmitter;
}
async function processEpochsForNetwork({
  chainId,
  path,
  toSaveSnapshot,
  networkKey,
  network,
  routeConfig,
  inboxRPC,
  outboxRPC,
  routerRPC,
  toWatch,
  transactionHandlers,
  emitter,
}: ProcessEpochParams) {
  const privKey = process.env.PRIVATE_KEY;
  // v6 providers for the typechain contract connections (the inbox chainId is detected via the fallback transport).
  const veaInboxContractProvider = new FallbackRpcProvider(inboxRPC, emitter);
  const veaOutboxContractProvider = new FallbackRpcProvider(outboxRPC, emitter, chainId);
  const veaInbox = getVeaInbox(
    routeConfig[network].veaInbox.address,
    privKey,
    veaInboxContractProvider,
    chainId,
    network
  );
  const veaOutbox = getVeaOutbox(
    routeConfig[network].veaOutbox.address,
    privKey,
    veaOutboxContractProvider,
    chainId,
    network
  );
  // v5 providers for the standalone reads / Arbitrum SDK path.
  const veaInboxProvider = new FallbackProviderV5(inboxRPC, emitter);
  const veaOutboxProvider = new FallbackProviderV5(outboxRPC, emitter);
  const veaRouterProvider = routerRPC && routerRPC.length > 0 ? new FallbackProviderV5(routerRPC, emitter) : undefined;
  let i = toWatch[networkKey].epochs.length - 1;
  let latestEpoch = toWatch[networkKey].epochs[i];
  const currentEpoch = Math.floor(Date.now() / (1000 * routeConfig[network].epochPeriod));
  if (latestEpoch != currentEpoch - 1 && network != Network.DEVNET) {
    toWatch[networkKey].epochs.push(currentEpoch - 1);
    latestEpoch = currentEpoch - 1;
    i++;
  }
  // Checks and saves the snapshot if needed
  if (toSaveSnapshot) {
    const TransactionHandler = getTransactionHandler(chainId, network) as any;
    const txnHandlerKey = `${routeConfig[network].veaInbox.address}_${currentEpoch}`;
    const transactionHandler =
      transactionHandlers[currentEpoch] ||
      new TransactionHandler({
        network,
        epoch: currentEpoch,
        veaInbox,
        veaOutbox,
        veaInboxProvider,
        veaOutboxProvider,
        veaRouterProvider,
        emitter,
      });
    const { updatedTransactionHandler, latestCount } = await saveSnapshot({
      chainId,
      veaInbox,
      veaOutbox,
      veaInboxProvider,
      veaOutboxProvider,
      network,
      epochPeriod: routeConfig[network].epochPeriod,
      count: toWatch[networkKey].count,
      transactionHandler,
    } as SaveSnapshotParams);
    const count = toWatch[networkKey].count;
    if (count == -1 || count != latestCount) {
      transactionHandlers[txnHandlerKey] = updatedTransactionHandler;
      toWatch[networkKey].count = latestCount;
    }
  }

  while (i >= 0) {
    const epoch = toWatch[networkKey].epochs[i];
    const claim = await getClaim({
      network,
      chainId,
      veaOutbox,
      veaOutboxProvider,
      epoch,
      epochPeriod: routeConfig[network].epochPeriod,
      emitter,
    });

    let updatedTransactions;
    if (path > BotPaths.CLAIMER && claim != null) {
      const checkAndChallengeResolveDeps: ChallengeAndResolveClaimParams = {
        chainId,
        claim,
        epoch,
        epochPeriod: routeConfig[network].epochPeriod,
        veaInbox,
        veaInboxProvider,
        veaOutboxProvider,
        veaRouterProvider,
        veaOutbox,
        transactionHandler: transactionHandlers[epoch],
        emitter,
      };
      updatedTransactions = await challengeAndResolveClaim(checkAndChallengeResolveDeps);
    }
    if (path == BotPaths.CLAIMER || path == BotPaths.BOTH) {
      const checkAndClaimParams: CheckAndClaimParams = {
        network,
        chainId,
        claim,
        epoch,
        epochPeriod: routeConfig[network].epochPeriod,
        veaInbox,
        veaInboxProvider,
        veaOutboxProvider,
        veaOutbox,
        transactionHandler: transactionHandlers[epoch],
        emitter,
      };
      updatedTransactions = await checkAndClaim(checkAndClaimParams);
    }

    if (updatedTransactions) {
      transactionHandlers[epoch] = updatedTransactions;
    } else if (epoch != currentEpoch - 1 && epoch != latestEpoch) {
      delete transactionHandlers[epoch];
      toWatch[networkKey].epochs.splice(i, 1);
    }
    i--;
  }
}

const wait = (ms: number): Promise<void> => new Promise((resolve: () => void) => setTimeout(resolve, ms));

if (require.main === module) {
  const shutDownSignal = new ShutdownSignal(false);
  watch(shutDownSignal);
}

