  startVerification(currentTimestamp: number): Promise<void>;
  verifySnapshot(currentTimestamp: number): Promise<void>;
  withdrawClaimDeposit(): Promise<void>;
  challengeClaim(): Promise<void>;
  withdrawChallengeDeposit(): Promise<void>;
  saveSnapshot(): Promise<void>;
  sendSnapshot(): Promise<void>;
  resolveChallengedClaim(sendSnapshotTxn: string): Promise<void>;
  routeSnapshot?(): Promise<void>;
}

export enum ContractType {
  INBOX = "inbox",
  OUTBOX = "outbox",
  ROUTER = "router",
}

export enum TransactionStatus {
  NOT_MADE = 0,
  PENDING = 1,
  NOT_FINAL = 2,
  FINAL = 3,
  EXPIRED = 4,
}

export type Transaction = {
  hash: string;
  broadcastedTimestamp: number;
};

export type Transactions = {
  claimTxn: Transaction | null;
  withdrawClaimDepositTxn: Transaction | null;
  startVerificationTxn: Transaction | null;
  verifySnapshotTxn: Transaction | null;
  challengeTxn: Transaction | null;
  withdrawChallengeDepositTxn: Transaction | null;
  saveSnapshotTxn: Transaction | null;
  sendSnapshotTxn: Transaction | null;
  executeSnapshotTxn: Transaction | null;
  devnetAdvanceStateTxn?: Transaction | null;
};

export const MAX_PENDING_TIME = 5 * 60 * 1000; // 5 minutes
export const MAX_PENDING_CONFIRMATIONS = 10;

export interface BaseTransactionHandlerConstructor {
  chainId: number;
  network: Network;
  epoch: number;
  veaInbox: any;
  veaOutbox: any;
  veaInboxProvider: JsonRpcProvider;
  veaOutboxProvider: JsonRpcProvider;
  veaRouterProvider?: JsonRpcProvider;
  emitter: typeof defaultEmitter;
  claim: ClaimStruct | null;
}

/**
 * Abstract base that implements all of the “status check” logic
 * and the shared handlers:
 *   - startVerification
 *   - verifySnapshot
 *   - withdrawClaimDeposit
 *   - withdrawChallengeDeposit
 *   - saveSnapshot
 *
 * Subclasses must implement:
 *   - makeClaim
 *   - challengeClaim
 *   - sendSnapshot
 *   - resolveChallengedClaim
 *   - (optionally) routeAssets
 */
export abstract class BaseTransactionHandler<Inbox, Outbox> implements ITransactionHandler {
  public chainId: number;
  public network: Network;
  public epoch: number;
  public veaInbox: Inbox;
  public veaOutbox: Outbox;
  public veaInboxProvider: JsonRpcProvider;
  public veaOutboxProvider: JsonRpcProvider;
  public veaRouterProvider?: JsonRpcProvider;
  public emitter: typeof defaultEmitter;
  public claim: ClaimStruct | null;
  public transactions: Transactions = {
    claimTxn: null,
    withdrawClaimDepositTxn: null,
    startVerificationTxn: null,
    verifySnapshotTxn: null,
    challengeTxn: null,
    withdrawChallengeDepositTxn: null,
    saveSnapshotTxn: null,
    sendSnapshotTxn: null,
    executeSnapshotTxn: null,
  };

  constructor({
    chainId,
    network,
    epoch,
    veaInbox,
    veaOutbox,
    veaInboxProvider,
    veaOutboxProvider,
    emitter,
    claim,
    veaRouterProvider,
  }: BaseTransactionHandlerConstructor) {
    this.chainId = chainId;
    this.network = network;
    this.epoch = epoch;
    this.veaInbox = veaInbox;
    this.veaOutbox = veaOutbox;
    this.veaInboxProvider = veaInboxProvider;
    this.veaOutboxProvider = veaOutboxProvider;
    this.veaRouterProvider = veaRouterProvider;
    this.emitter = emitter;
    this.claim = claim;
  }

  public async checkTransactionStatus(
    trnx: Transaction | null,
    contract: ContractType,
    currentTime: number
  ): Promise<TransactionStatus> {
    let provider: JsonRpcProvider;
    switch (contract) {
      case ContractType.INBOX:
        provider = this.veaInboxProvider;
        break;
      case ContractType.OUTBOX:
        provider = this.veaOutboxProvider;
        break;
      case ContractType.ROUTER:
        provider = this.veaRouterProvider;
        break;
    }

    if (!trnx) return TransactionStatus.NOT_MADE;

    const receipt = await provider.getTransactionReceipt(trnx.hash);
    if (!receipt) {
      this.emitter.emit(BotEvents.TXN_PENDING, trnx.hash);
      if (currentTime - trnx.broadcastedTimestamp > MAX_PENDING_TIME) {
        this.emitter.emit(BotEvents.TXN_EXPIRED, trnx.hash);
        return TransactionStatus.EXPIRED;
      }
      return TransactionStatus.PENDING;
    }

    const block = await provider.getBlock("latest");
    const confirmations = block.number - receipt.blockNumber;
    if (confirmations >= MAX_PENDING_CONFIRMATIONS) {
      this.emitter.emit(BotEvents.TXN_FINAL, trnx.hash, confirmations);
      return TransactionStatus.FINAL;
    }

    this.emitter.emit(BotEvents.TXN_NOT_FINAL, trnx.hash, MAX_PENDING_CONFIRMATIONS - confirmations);
    return TransactionStatus.NOT_FINAL;
  }

  public async toSubmitTransaction(
    trnx: Transaction | null,
    contract: ContractType,
    currentTime: number
  ): Promise<boolean> {
    const status = await this.checkTransactionStatus(trnx, contract, currentTime);
    if (status === TransactionStatus.PENDING || status === TransactionStatus.NOT_FINAL) return false;
    return true;
  }

  public async startVerification(currentTimestamp: number) {
    this.emitter.emit(BotEvents.STARTING_VERIFICATION, this.epoch);
    if (!this.claim) throw new ClaimNotSetError();

    const now = Date.now();
    const toSubmit = await this.toSubmitTransaction(this.transactions.startVerificationTxn, ContractType.OUTBOX, now);
    if (!toSubmit) return;

    const cfg = getBridgeConfig(this.chainId);
    const timeOver =
      currentTimestamp -
      Number(this.claim.timestampClaimed) -
      cfg.sequencerDelayLimit -
      cfg.routeConfig[this.network].epochPeriod;

    if (timeOver < 0) {
      this.emitter.emit(BotEvents.VERIFICATION_CANT_START, this.epoch, -timeOver);
      return;
    }

    const tx = await (this.veaOutbox as any).startVerification(this.epoch, this.claim);
    this.emitter.emit(BotEvents.TXN_MADE, tx.hash, this.epoch, "Start Verification");
    this.transactions.startVerificationTxn = {
      hash: tx.hash,
      broadcastedTimestamp: now,
    };
  }

  public async verifySnapshot(currentTimestamp: number) {
    this.emitter.emit(BotEvents.VERIFYING_SNAPSHOT, this.epoch);
    if (!this.claim) throw new ClaimNotSetError();

    const now = Date.now();
    const toSubmit = await this.toSubmitTransaction(this.transactions.verifySnapshotTxn, ContractType.OUTBOX, now);
    if (!toSubmit) return;

    const cfg = getBridgeConfig(this.chainId);
    const timeLeft = currentTimestamp - Number(this.claim.timestampVerification) - cfg.minChallengePeriod;

    if (timeLeft < 0) {
      this.emitter.emit(BotEvents.CANT_VERIFY_SNAPSHOT, this.epoch, -timeLeft);
      return;
    }

    const tx = await (this.veaOutbox as any).verifySnapshot(this.epoch, this.claim);
    this.emitter.emit(BotEvents.TXN_MADE, tx.hash, this.epoch, "Verify Snapshot");
    this.transactions.verifySnapshotTxn = {
      hash: tx.hash,
      broadcastedTimestamp: now,
    };
  }

  public async withdrawClaimDeposit() {
    this.emitter.emit(BotEvents.WITHDRAWING_CLAIM_DEPOSIT, this.epoch);
    if (!this.claim) throw new ClaimNotSetError();

    const now = Date.now();
    const toSubmit = await this.toSubmitTransaction(
      this.transactions.withdrawClaimDepositTxn,
      ContractType.OUTBOX,
      now
    );
    if (!toSubmit) return;

    const tx = await (this.veaOutbox as any).withdrawClaimDeposit(this.epoch, this.claim);
    this.emitter.emit(BotEvents.TXN_MADE, tx.hash, this.epoch, "Withdraw Claim Deposit");
    this.transactions.withdrawClaimDepositTxn = {
      hash: tx.hash,
      broadcastedTimestamp: now,
    };
  }

  public async withdrawChallengeDeposit() {
    this.emitter.emit(BotEvents.WITHDRAWING_CHALLENGE_DEPOSIT, this.epoch);
    if (!this.claim) throw new ClaimNotSetError();

    const now = Date.now();
    const toSubmit = await this.toSubmitTransaction(
      this.transactions.withdrawChallengeDepositTxn,
      ContractType.OUTBOX,
      now
    );
    if (!toSubmit) return;

    const tx = await (this.veaOutbox as any).withdrawChallengeDeposit(this.epoch, this.claim);
    this.emitter.emit(BotEvents.TXN_MADE, tx.hash, this.epoch, "Withdraw Challenge Deposit");
    this.transactions.withdrawChallengeDepositTxn = {
      hash: tx.hash,
      broadcastedTimestamp: now,
    };
  }

  public async saveSnapshot() {
    this.emitter.emit(BotEvents.SAVING_SNAPSHOT, this.epoch);

    const now = Date.now();
    const toSubmit = await this.toSubmitTransaction(this.transactions.saveSnapshotTxn, ContractType.INBOX, now);
    if (!toSubmit) return;

    const tx = await (this.veaInbox as any).saveSnapshot();
    this.emitter.emit(BotEvents.TXN_MADE, tx.hash, this.epoch, "Save Snapshot");
    this.transactions.saveSnapshotTxn = {
      hash: tx.hash,
      broadcastedTimestamp: now,
    };
  }

  public abstract makeClaim(stateRoot: string): Promise<void>;
  public abstract challengeClaim(): Promise<void>;
  public abstract sendSnapshot(): Promise<void>;
  public abstract resolveChallengedClaim(sendSnapshotTxn: string): Promise<void>;
}

import {
  VeaInboxArbToGnosis,
  VeaOutboxArbToGnosis,
  VeaOutboxArbToGnosisDevnet,
} from "../../../../contracts/typechain-types";
import { toBigInt, Wallet } from "ethers";
import {
  BaseTransactionHandler,
  BaseTransactionHandlerConstructor,
  ContractType,
  Transaction,
  Transactions,
} from "./baseTransactionHandler";
import { BotEvents } from "../botEvents";
import { ClaimNotSetError } from "../errors";
import { getBridgeConfig, Network } from "../../consts/bridgeRoutes";
import { getWETH } from "../ethers";
import { messageExecutor } from "../arbMsgExecutor";

export class ArbToGnosisTransactionHandler extends BaseTransactionHandler<VeaInboxArbToGnosis, VeaOutboxArbToGnosis> {
  constructor(opts: BaseTransactionHandlerConstructor) {
    super(opts);
  }

  public async approveWeth(): Promise<void> {
    const { depositToken, routeConfig } = getBridgeConfig(this.chainId);
    const { veaOutbox, deposit } = routeConfig[this.network];
    const signer = this.veaOutbox.runner as Wallet;

    const weth = getWETH(depositToken, signer);
    const currentAllowance: bigint = await weth.allowance(signer.address, veaOutbox.address);
    if (currentAllowance < deposit) {
      const approvalAmount = deposit * BigInt(10); // Approving for 10 claims
      const approveTx = await weth.approve(veaOutbox.address, approvalAmount);
      await approveTx.wait();
    }
  }

  public async makeClaim(stateRoot: string): Promise<void> {
    this.emitter.emit(BotEvents.CLAIMING, this.epoch);
    const now = Date.now();
    const toSubmit = await this.toSubmitTransaction(this.transactions.claimTxn, ContractType.OUTBOX, now);
    if (!toSubmit) return;

    // Approves WETH for the claim if not already approved
    await this.approveWeth();

    const gasEstimate = await this.veaOutbox["claim(uint256,bytes32)"].estimateGas(this.epoch, stateRoot);
    const tx = await this.veaOutbox.claim(this.epoch, stateRoot, { gasLimit: gasEstimate });
    this.emitter.emit(BotEvents.TXN_MADE, tx.hash, this.epoch, "Claim");
    this.transactions.claimTxn = { hash: tx.hash, broadcastedTimestamp: now };
  }

  public async challengeClaim(): Promise<void> {
    this.emitter.emit(BotEvents.CHALLENGING, this.epoch);
    if (!this.claim) throw new ClaimNotSetError();
    const now = Date.now();
    const toSubmit = await this.toSubmitTransaction(this.transactions.challengeTxn, ContractType.OUTBOX, now);
    if (!toSubmit) return;

    const gasEstimate = await this.veaOutbox[
      "challenge(uint256,(bytes32,address,uint32,uint32,uint32,uint8,address))"
    ].estimateGas(this.epoch, this.claim);
    const { routeConfig } = getBridgeConfig(this.chainId);
    const { deposit } = routeConfig[this.network];
    const maxFeePerGasProfitable = deposit / (toBigInt(gasEstimate) * BigInt(6));
    // Set a reasonable maxPriorityFeePerGas but ensure it's lower than maxFeePerGas
    let maxPriorityFeePerGasMEV = BigInt(6667000000000); // 6667 gwei
    // Ensure maxPriorityFeePerGas <= maxFeePerGas
    if (maxPriorityFeePerGasMEV > maxFeePerGasProfitable) {
      maxPriorityFeePerGasMEV = maxFeePerGasProfitable;
    }
    const tx = await this.veaOutbox.challenge(this.epoch, this.claim, {
      maxFeePerGas: maxFeePerGasProfitable,
      maxPriorityFeePerGas: maxPriorityFeePerGasMEV,
      gasLimit: gasEstimate,
    });
    this.emitter.emit(BotEvents.TXN_MADE, tx.hash, this.epoch, "Challenge");
    this.transactions.challengeTxn = { hash: tx.hash, broadcastedTimestamp: now };
  }

  public async sendSnapshot(): Promise<void> {
    this.emitter.emit(BotEvents.SENDING_SNAPSHOT, this.epoch);
    if (!this.claim) throw new ClaimNotSetError();
    const now = Date.now();
    const toSubmit = await this.toSubmitTransaction(this.transactions.sendSnapshotTxn, ContractType.INBOX, now);
    if (!toSubmit) return;

    const ambGasLimit = BigInt(3000000);
    const tx = await this.veaInbox.sendSnapshot(this.epoch, ambGasLimit, this.claim);
    this.emitter.emit(BotEvents.TXN_MADE, tx.hash, this.epoch, "Send Snapshot");
    this.transactions.sendSnapshotTxn = { hash: tx.hash, broadcastedTimestamp: now };
  }

  public async resolveChallengedClaim(sendSnapshotTxn: string): Promise<void> {
    this.emitter.emit(BotEvents.EXECUTING_SNAPSHOT, this.epoch);
    if (!this.claim) throw new ClaimNotSetError();
    const now = Date.now();
    const toSubmit = await this.toSubmitTransaction(this.transactions.executeSnapshotTxn, ContractType.ROUTER, now);
    if (!toSubmit) return;
    const msgExecuteTrnx = await messageExecutor(sendSnapshotTxn, this.veaInboxProvider, this.veaRouterProvider);
    this.emitter.emit(BotEvents.TXN_MADE, msgExecuteTrnx.hash, this.epoch, "Execute Snapshot");
    this.transactions.executeSnapshotTxn = {
      hash: msgExecuteTrnx.hash,
      broadcastedTimestamp: now,
    };
  }
}

/**
 * Devnet-only extension for Arb→Gnosis handler
 */
export interface GnosisDevnetTransactions extends Transactions {
  devnetAdvanceStateTxn: Transaction | null;
}

export class ArbToGnosisDevnetTransactionHandler extends ArbToGnosisTransactionHandler {
  public veaOutboxDevnet: VeaOutboxArbToGnosisDevnet;
  public transactions: GnosisDevnetTransactions = {
    ...(this.transactions as Transactions),
    devnetAdvanceStateTxn: null,
  };

  constructor(opts: BaseTransactionHandlerConstructor) {
    super(opts);
    this.veaOutboxDevnet = opts.veaOutbox as VeaOutboxArbToGnosisDevnet;
  }

  /**
   * Advance the devnet state via a special call on the Devnet outbox.
   */
  public async devnetAdvanceState(stateRoot: string): Promise<void> {
    this.emitter.emit(BotEvents.ADV_DEVNET, this.epoch);
    const now = Date.now();
    const toSubmit = await this.toSubmitTransaction(this.transactions.devnetAdvanceStateTxn, ContractType.OUTBOX, now);
    if (!toSubmit) return;
    await this.approveWeth();
    const { routeConfig } = getBridgeConfig(this.chainId);
    const { deposit } = routeConfig[Network.DEVNET];
    const tx = await this.veaOutboxDevnet.devnetAdvanceState(this.epoch, stateRoot, {
      value: deposit,
    });
    this.emitter.emit(BotEvents.TXN_MADE, tx.hash, this.epoch, "Advance Devnet State");
    this.transactions.devnetAdvanceStateTxn = { hash: tx.hash, broadcastedTimestamp: now };
  }
}

import {
  ChildTransactionReceipt,
  ArbitrumProvider,
  ChildToParentMessageWriter,
  ChildToParentMessageStatus,
} from "@arbitrum/sdk";
import { Wallet } from "@ethersproject/wallet";
import { JsonRpcProvider, TransactionReceipt } from "@ethersproject/providers";
import { Signer } from "@ethersproject/abstract-signer";
import { ContractTransaction } from "@ethersproject/contracts";

/**
 * Execute the child-to-parent (arbitrum-to-ethereum) message,
 * for reference see: https://docs.arbitrum.io/sdk/reference/message/ChildToParentMessage
 *
 * @param trnxHash Hash of the transaction
 * @param childJsonRpc L2 provider
 * @param parentJsonRpc L1 provider
 * @returns Execution transaction for the message
 *
 * */
async function messageExecutor(
  trnxHash: string,
  childJsonRpc: JsonRpcProvider,
  parentProvider: JsonRpcProvider
): Promise<ContractTransaction> {
  const PRIVATE_KEY = process.env.PRIVATE_KEY;
  const childProvider = new ArbitrumProvider(childJsonRpc);

  const childReceipt: TransactionReceipt = await childProvider.getTransactionReceipt(trnxHash);
  if (!childReceipt) {
    throw new Error(`Transaction receipt not found for hash: ${trnxHash}`);
  }

  const messageReceipt = new ChildTransactionReceipt(childReceipt);
  const parentSigner: Signer = new Wallet(PRIVATE_KEY, parentProvider);

  const messages = await messageReceipt.getChildToParentMessages(parentSigner);
  const childToParentMessage: ChildToParentMessageWriter = messages[0];
  if (!childToParentMessage) {
    throw new Error("No child-to-parent messages found");
  }

  // Execute the message
  const res = await childToParentMessage.execute(childProvider);
  return res;
}

/**
 *
 * @param trnxHash Hash of the transaction
 * @param childJsonRpc L2 provider
 * @param parentJsonRpc L1 provider
 * @returns status of the message: 0 - not ready, 1 - ready
 *
 */
async function getMessageStatus(
  trnxHash: string,
  childJsonRpc: JsonRpcProvider,
  parentJsonRpc: JsonRpcProvider
): Promise<ChildToParentMessageStatus> {
  const PRIVATE_KEY = process.env.PRIVATE_KEY;
  const childProvider = new ArbitrumProvider(childJsonRpc);

  let childReceipt: TransactionReceipt | null;

  childReceipt = await childProvider.getTransactionReceipt(trnxHash);
  if (!childReceipt) {
    throw new Error(`Transaction receipt not found for hash: ${trnxHash}`);
  }
  const messageReceipt = new ChildTransactionReceipt(childReceipt);
  const parentSigner: Signer = new Wallet(PRIVATE_KEY, parentJsonRpc);
  const messages = await messageReceipt.getChildToParentMessages(parentSigner);
  const childToParentMessage = messages[0];
  if (!childToParentMessage) {
    console.error("No child-to-parent messages found");
  }
  const status = await childToParentMessage.status(childProvider);
  return status;
}

